    slug: "is-guinness-a-stout",
    title: "Is Guinness a Stout? A Straight Answer",
    excerpt: "Yes — but understanding exactly what \"stout\" means, and where Guinness fits within the broader stout family, is genuinely useful.",
    content: "Guinness is unambiguously a stout, and it's arguably the single most globally recognized example of the style — but understanding what \"stout\" actually means helps place it within a broader, more varied category.\n\n## What Defines a Stout\n\nStout is a dark beer style characterized by the use of roasted malt or roasted barley, producing dark color and characteristic coffee, chocolate, and roasted flavor notes — historically evolved from and closely related to porter, another dark beer style, with the lines between the two categories often blurring in practice.\n\n## Where Guinness Fits Specifically\n\nGuinness Draught is specifically a dry (or \"Irish\") stout — a substyle characterized by a drier finish and more pronounced roasted bitterness than sweeter stout variations, generally lower in alcohol than many craft stout interpretations, and famous for its nitrogen dispensing system creating the smooth, cascading pour.\n\n## Stout's Broader Family\n\nBeyond dry/Irish stout, the stout category includes milk stout (sweetened with lactose, which yeast can't ferment, leaving residual sweetness), oatmeal stout (using oats for a smoother, silkier mouthfeel), imperial stout (a much higher-ABV, more intense variation), and many other substyles — a genuinely wide range within one dark-beer family.\n\n## Why People Sometimes Question the Classification\n\nGuinness's relatively light body and lower alcohol content compared to some craft imperial stouts might lead people to assume it's a lighter, less \"serious\" category than stout implies — but the stout classification is about the roasted-malt flavor profile and dark color, not necessarily about body weight or alcohol strength, both of which vary considerably across the stout family.\n\n## Guinness's Historical Significance\n\nGuinness didn't just happen to be a stout — the brand's decades of dominance and marketing have made it, for many casual beer drinkers globally, the primary reference point that defines what \"stout\" even means, even though the broader style category existed and evolved well before and independent of the specific Guinness brand.\n\n## The Bottom Line\n\nGuinness is genuinely and unambiguously a stout — specifically a dry/Irish stout, one substyle within a much broader dark-beer family that also includes milk stout, oatmeal stout, and imperial stout, each with meaningfully different character despite sharing the same core roasted-malt foundation.",
